function defaultBadge() {
  return Buffer.from(DEFAULT_BADGE_B64, 'base64');
}

/** 读后台配的班徽地址 */
async function configuredUrl() {
  const sql = getSql();
  const uid = await systemUserId(sql);
  if (!uid) return '';
  const rows = await sql`
    select data_value from user_data
     where user_id = ${uid} and data_key = ${CONTENT_KEY} limit 1
  `;
  if (!rows.length) return '';
  const doc = jsonCol(rows[0].data_value) || {};
  const cfg = (doc.site_config && typeof doc.site_config === 'object') ? doc.site_config : {};
  const url = String(cfg.badgeUrl || '').trim();
  return /^https?:\/\//i.test(url) ? url : '';
}

export default async function handler(req, res) {
  if (handlePreflight(req, res)) return;
  cors(req, res);

  /* ① 先试后台配的直链 */
  try {
    const url = await configuredUrl();
    if (url) {
      const ctl = typeof AbortController !== 'undefined' ? new AbortController() : null;
      const timer = ctl ? setTimeout(() => { try { ctl.abort(); } catch (e) {} }, FETCH_TIMEOUT_MS) : null;
      let r = null;
      try {
        r = await fetch(url, ctl ? { signal: ctl.signal, cf: { cacheTtl: 3600, cacheEverything: true } } : { cf: { cacheTtl: 3600, cacheEverything: true } });
      } finally {
        if (timer) clearTimeout(timer);
      }
      if (r && r.ok) {
        const type = r.headers.get('content-type') || '';
        if (/^image\//i.test(type)) {
          const buf = await r.arrayBuffer();
          if (buf.byteLength > 0 && buf.byteLength <= MAX_BYTES) {
            res.statusCode = 200;
            res.setHeader('Content-Type', type);
            res.setHeader('Cache-Control', 'public, max-age=86400');
            res.setHeader('Access-Control-Allow-Origin', '*');
            res.setHeader('X-Badge-Source', 'proxy');
            res.end(Buffer.from(buf));
            return;
          }
        }
      }
    }
  } catch (e) {
    /* 图床挂了不报错，走下面的内嵌图 */
    console.warn('[badge] 取配置的班徽失败，改用内嵌图：', String(e && e.message || e).slice(0, 120));
  }

  /* ② 内嵌兜底 —— 永远可用 */
  try {
    const buf = defaultBadge();
    res.statusCode = 200;
    res.setHeader('Content-Type', 'image/png');
    res.setHeader('Cache-Control', 'public, max-age=86400');
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('X-Badge-Source', 'embedded');
    res.end(buf);
    return;
  } catch (e) {
    return fail(res, 500, '班徽读取失败：' + String(e.message || e).slice(0, 120));
  }
}
